/* Standalone HyperFrames timeline and living-world lab synchronization. */
(() => {
  "use strict";

  // The slideshow advances by explicit navigation. Generic player clicks must
  // not start the composition clock while someone operates a lab or a video.
  // Apply this in the composition too, for the wrapper generated by `present`.
  try {
    const player = window.frameElement?.getRootNode()?.host;
    if (player?.localName === "hyperframes-player" && player.closest("hyperframes-slideshow")) {
      player.setAttribute("disable-click-to-play", "");
    }
  } catch {
    // A cross-origin host retains control of its player configuration.
  }

  const sceneElements = Array.from(
    document.querySelectorAll(".scene[data-composition-id][data-start][data-duration]"),
  ).filter((element) => !element.parentElement.closest(".scene[data-composition-id]"));
  const scenes = sceneElements.map((element) => ({
    id: element.dataset.compositionId,
    start: Number(element.dataset.start),
    duration: Number(element.dataset.duration),
    element,
  })).sort((a, b) => a.start - b.start);

  if (!window.gsap || !scenes.length || scenes.some((scene) =>
    !scene.id || !Number.isFinite(scene.start) || !Number.isFinite(scene.duration) || scene.duration <= 0
  )) {
    throw new Error("The presentation needs GSAP and valid, timed scenes.");
  }

  const duration = Math.max(...scenes.map((scene) => scene.start + scene.duration));
  let activeId = null;
  let currentTime = -1;

  function updateVisibility(value) {
    const time = Math.max(0, Math.min(duration, Number(value) || 0));
    const active = scenes.find((scene) => time >= scene.start && time < scene.start + scene.duration)
      ?? (time === duration ? scenes.at(-1) : null);
    const nextId = active?.id ?? null;

    if (nextId !== activeId) {
      const previousId = activeId;
      activeId = nextId;
      for (const scene of scenes) {
        const visible = scene === active;
        scene.element.style.opacity = visible ? "1" : "0";
        scene.element.style.visibility = visible ? "visible" : "hidden";
        scene.element.style.pointerEvents = visible ? "auto" : "none";
        scene.element.setAttribute("aria-hidden", String(!visible));
        scene.element.inert = !visible;
      }
      document.documentElement.dataset.activeScene = nextId ?? "";
      document.dispatchEvent(new CustomEvent("living-world:scene", {
        detail: { id: nextId, previousId, time, element: active?.element ?? null },
      }));
    }

    if (time !== currentTime) {
      currentTime = time;
      document.dispatchEvent(new CustomEvent("living-world:time", {
        detail: { time, id: nextId },
      }));
    }
  }

  const clock = { value: 0 };
  const root = window.gsap.timeline({ paused: true });
  root.to(clock, { value: duration, duration, ease: "none" });
  root.eventCallback("onUpdate", () => updateVisibility(root.time()));
  window.__timelines = window.__timelines || {};
  window.__timelines.root = root;
  window.__hfSetTime = (time) => {
    root.seek(Math.max(0, Math.min(duration, Number(time) || 0)), false).pause();
    updateVisibility(root.time());
  };
  updateVisibility(0);

  // Slide navigation owns the timeline. Native media owns its playback clock.
  // In particular, pausing/seeking a video must never seek this root timeline.
  document.addEventListener("keydown", (event) => {
    if (event.target instanceof Element && event.target.closest("video, audio") &&
      ["ArrowLeft", "ArrowRight", " ", "Backspace", "f", "F"].includes(event.key)) {
      event.stopPropagation();
    }
  }, true);

  function postTimeline() {
    if (window.parent === window) return;
    const origin = new URL(document.baseURI).origin;
    window.parent.postMessage({
      source: "hf-preview",
      type: "timeline",
      durationInFrames: Math.round(duration * 30),
      scenes: scenes.map(({ id, start, duration: length }) => ({ id, start, duration: length })),
    }, origin === "null" ? "*" : origin);
  }
  postTimeline();
  if (document.readyState === "complete") {
    setTimeout(postTimeline, 300);
  } else {
    window.addEventListener("load", () => setTimeout(postTimeline, 300), { once: true });
  }

  // The official slideshow owns slide/media sync. This channel extension sends
  // only lab inputs; the audience recomputes results with the actual simulation.
  if (typeof BroadcastChannel === "undefined") return;
  let host;
  try {
    host = window.parent === window ? window : window.parent;
    void host.location.pathname;
  } catch {
    return;
  }
  const audience = new URLSearchParams(host.location.search).get("mode") === "audience";
  const channel = new BroadcastChannel("hf-slideshow:" + host.location.pathname);
  const sender = window.crypto?.randomUUID?.() ?? String(Math.random());
  let queuedState = null;
  let remoteSender = null;
  let remoteSequence = -1;
  let sequence = 0;
  let disposed = false;

  function lab() { return window.LivingWorldLab; }
  function publish() {
    if (audience || disposed) return;
    const state = lab()?.snapshot?.();
    if (state) channel.postMessage({ type: "living-world:lab-snapshot", sender, sequence: ++sequence, state });
  }
  function requestSnapshot() {
    if (audience && !disposed) channel.postMessage({ type: "living-world:lab-request", sender });
  }
  function restoreLatest() {
    if (!audience || !queuedState || typeof lab()?.restore !== "function") return;
    const state = queuedState;
    queuedState = null;
    Promise.resolve(lab().restore(state)).catch((error) => {
      console.warn("[living-world] Could not restore the audience lab:", error);
    });
  }

  channel.addEventListener("message", (event) => {
    const message = event.data;
    if (!message || message.sender === sender) return;
    if (message.type === "living-world:lab-request") {
      publish();
    } else if (audience && message.type === "living-world:lab-snapshot" &&
      typeof message.sender === "string" && Number.isFinite(message.sequence) && message.state) {
      if (message.sender !== remoteSender) {
        remoteSender = message.sender;
        remoteSequence = -1;
      }
      if (message.sequence <= remoteSequence) return;
      remoteSequence = message.sequence;
      queuedState = message.state;
      restoreLatest();
    }
  });
  document.addEventListener("living-world:lab-state", () => {
    if (audience) restoreLatest();
    else publish();
  });

  function onLabReady() {
    Promise.resolve(lab()?.ready).then(() => {
      if (disposed) return;
      restoreLatest();
      if (audience) requestSnapshot();
      else publish();
    });
  }
  if (document.readyState === "complete") onLabReady();
  else window.addEventListener("load", onLabReady, { once: true });
  window.addEventListener("pagehide", () => { disposed = true; channel.close(); }, { once: true });
})();
